import { authorize } from "../payments/gateway";
import { persist } from "./repository";

const MAX_ATTEMPTS = 3;

async function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function processOrder(order: Order): Promise<string> {
  let lastError: unknown;
  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
    try {
      const auth = await authorize(order.totalCents);
      return await persist(order, auth);
    } catch (ex) {
      lastError = ex;
      await sleep(2 ** attempt * 100);
    }
  }
  throw lastError;
}

export interface Order {
  id: string;
  totalCents: number;
  lineItems: LineItem[];
}

export interface LineItem {
  sku: string;
  quantityUnits: number;
}

